    /**
     * @method
     * @name coinone#fetchCurrencies
     * @description fetches all available currencies on an exchange
     * @see https://docs.coinone.co.kr/reference/currencies
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    public CompletableFuture<Object> fetchCurrencies(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            Map<String, Object> response = (this.v2PublicGetCurrencies(parameters)).join();
            //
            //     {
            //         "result": "success",
            //         "error_code": "0",
            //         "server_time": 1701054555578,
            //         "currencies": [
            //           {
            //             "name": "Polygon",
            //             "symbol": "MATIC",
            //             "deposit_status": "normal",
            //             "withdraw_status": "normal",
            //             "deposit_confirm_count": 150,
            //             "max_precision": 8,
            //             "deposit_fee": "0.0",
            //             "withdrawal_min_amount": "1.0",
            //             "withdrawal_fee": "3.0"
            //           }
            //         ]
            //     }
            //
            List<Object> currencies = (List<Object>) this.safeList(response, "currencies", new ArrayList<Object>(Arrays.asList()));
            return this.parseCurrencies(currencies);
        });

    }

    public Object parseCurrency(Object rawCurrency)
    {
        String id = this.safeString(rawCurrency, "symbol");
        String code = this.safeCurrencyCode(id, (Map<String, Object>) null);
        Boolean isWithdrawEnabled = java.util.Objects.equals(this.safeString(rawCurrency, "withdraw_status", ""), "normal");
        Boolean isDepositEnabled = java.util.Objects.equals(this.safeString(rawCurrency, "deposit_status", ""), "normal");
        String type = "fiat";
        if (!java.util.Objects.equals(code, "KRW"))
        {
            type = "crypto";
        }
        return this.safeCurrencyStructure(Helpers.newMap(
            "id", id,
            "code", code,
            "info", rawCurrency,
            "name", this.safeString(rawCurrency, "name"),
            "active", null,
            "deposit", isDepositEnabled,
            "withdraw", isWithdrawEnabled,
            "fee", this.safeNumber(rawCurrency, "withdrawal_fee", (Object) null),
            "precision", this.parseNumber(this.parsePrecision(this.safeString(rawCurrency, "max_precision"))),
            "limits", new HashMap<String, Object>() {{
                put( "amount", new HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "withdraw", new HashMap<String, Object>() {{
                    put( "min", Coinone.this.safeNumber(rawCurrency, "withdrawal_min_amount", (Object) null) );
                    put( "max", null );
                }} );
            }},
            "networks", new HashMap<String, Object>() {{}},
            "type", type
        ));
    }

    /**
     * @method
     * @name coinone#fetchMarkets
     * @description retrieves data on all markets for coinone
     * @see https://docs.coinone.co.kr/v1.0/reference/tickers
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public CompletableFuture<Object> fetchMarkets(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "quote_currency", "KRW" );
            }};
            Map<String, Object> response = (this.v2PublicGetTickerNewQuoteCurrency(request)).join();
            //
            //     {
            //         "result": "success",
            //         "error_code": "0",
            //         "server_time": 1701067923060,
            //         "tickers": [
            //             {
            //                 "quote_currency": "krw",
            //                 "target_currency": "stg",
            //                 "timestamp": 1701067920001,
            //                 "high": "667.5",
            //                 "low": "667.5",
            //                 "first": "667.5",
            //                 "last": "667.5",
            //                 "quote_volume": "0.0",
            //                 "target_volume": "0.0",
            //                 "best_asks": [
            //                     {
            //                         "price": "777.0",
            //                         "qty": "73.9098"
            //                     }
            //                 ],
            //                 "best_bids": [
            //                     {
            //                         "price": "690.8",
            //                         "qty": "40.7768"
            //                     }
            //                 ],
            //                 "id": "1701067920001001"
            //             }
            //         ]
            //     }
            //
            List<Object> tickers = (List<Object>) this.safeList(response, "tickers", new ArrayList<Object>(Arrays.asList()));
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            for (var i = 0; i < ((List<?>)tickers).size(); i++)
            {
                Map<String, Object> entry = (Map<String, Object>) this.safeDict(tickers, i, (Object) null);
                String id = this.safeString(entry, "id");
                String baseId = this.safeStringUpper(entry, "target_currency");
                String quoteId = this.safeStringUpper(entry, "quote_currency");
                String base = this.safeCurrencyCode(baseId, (Map<String, Object>) null);
                String quote = this.safeCurrencyCode(quoteId, (Map<String, Object>) null);
                if ((java.util.Objects.equals(base, null)) || (java.util.Objects.equals(quote, null)))
                {
                    continue;
                }
                ((List<Object>)result).add(Helpers.newMap(
                    "id", id,
                    "symbol", ((base + "/") + quote),
                    "base", base,
                    "quote", quote,
                    "settle", null,
                    "baseId", baseId,
                    "quoteId", quoteId,
                    "settleId", null,
                    "type", "spot",
                    "spot", true,
                    "margin", false,
                    "swap", false,
                    "future", false,
                    "option", false,
                    "active", null,
                    "contract", false,
                    "linear", null,
                    "inverse", null,
                    "contractSize", null,
                    "expiry", null,
                    "expiryDatetime", null,
                    "strike", null,
                    "optionType", null,
                    "precision", new HashMap<String, Object>() {{
                        put( "amount", Coinone.this.parseNumber("1e-4") );
                        put( "price", Coinone.this.parseNumber("1e-4") );
                        put( "cost", Coinone.this.parseNumber("1e-8") );
                    }},
                    "limits", new HashMap<String, Object>() {{
                        put( "leverage", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "amount", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "price", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "cost", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                    }},
                    "created", null,
                    "info", entry
                ));
            }
            return result;
        });

    }

    public Object parseBalance(Object response)
    {
        Map<String, Object> result = new HashMap<String, Object>() {{
            put( "info", response );
        }};
        Object balances = this.omit(response, new ArrayList<Object>(Arrays.asList("errorCode", "result", "normalWallets")));
        List<Object> currencyIds = Helpers.objectKeys(balances);
        for (var i = 0; i < ((List<?>)currencyIds).size(); i++)
        {
            Object currencyId = (currencyIds == null || i < 0 || i >= currencyIds.size() ? null : currencyIds.get(i));
            Map<String, Object> balance = (Map<String, Object>) this.safeDict(balances, currencyId, (Object) null);
            String code = this.safeCurrencyCode((String) (currencyId), (Map<String, Object>) null);
            Map<String, Object> account = (Map<String, Object>) this.account();
            account.put("free", this.safeString(balance, "avail"));
            account.put("total", this.safeString(balance, "balance"));
            if (!java.util.Objects.equals(code, null))
            {
                result.put((String)code, account);
            }
        }
        return this.safeBalance(result);
    }

